	regionKind = "plane",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Skywall is the realm of air, one of the four domains of the Elemental Plane. It is an endless sky of storms and currents, without ground beneath it or a ceiling above. Its master is {link:al-akir}Al'Akir{/link} the Windlord, and its native children are the spirits and elementals of the wind. For most of the peoples of {link:azeroth}Azeroth{/link}, Skywall is only a name in the lore of shamans. For the {link:skyborne}Skyborne{/link} it has been home for ten thousand years.]=],
		},
		{
			title = "Origins",
			text = [=[The elemental lords once raged across the young world. In the first age they served the Old Gods, and when the titans' servants broke that dark empire, the elementals were cast out of the world and bound in a realm apart. Each lord was given his own domain. The air fell to {link:al-akir}Al'Akir{/link}. Since then the wind of Skywall has blown beyond the sight of mortals, and few who entered it have returned to speak of it.]=],
		},
		{
			title = "The Hidden Isles",
			text = [=[In the long ages after the {link:war-of-the-ancients}War of the Ancients{/link}, elves fleeing Eldre'Thalas found shelter in Skywall. Spirits of the wind raised their land into the sky and set it in a quiet corner of the realm, where the {link:al-akir}Windlord{/link}'s eye did not fall. The {link:skyborne}shen'dorei{/link} built there a scattering of island provinces. {link:zephras-isle}Zephras Isle{/link} was one. Anvilas and Siroccas, with their towns of Shen'dramar and New Eldre'naar, were others. Once, currents of wind called skystreams carried travellers from isle to isle. Those roads have long been closed.]=],
		},
		{
			title = "The Present Day",
			text = [=[The shelter has failed. The spirits that guarded the isles vanished long ago, and the {link:anchor-pylons}anchor pylons{/link} that held {link:zephras-isle}Zephras{/link} in its place were also the wards that hid it. Those wards are down. A lord of the east wind has seen the island with his own eyes, and he has promised that {link:al-akir}Al'Akir{/link} will hear of it. No {link:skyborne}shen'dorei{/link} can say when the Windlord will turn toward them. All of them know that he will.]=],
		},
	},
})

Add({
	id = "zephras-isle",
	title = "Zephras Isle",
	aliases = { "Zephras" },
	faction = "Alliance and Horde",
