	regionKind = "zone",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Zephras Isle floats in {link:skywall}Skywall{/link}, the realm of air, far from any shore of {link:azeroth}Azeroth{/link}. It is the home of the {link:skyborne}Skyborne{/link}, the elves who call themselves shen'dorei. Great trees rise over its northern groves, blue highlands roll across its middle, and on its south-eastern edge stands the port of {link:valanaar}Valanaar{/link}. Waterfalls spill from its cliffs into open sky. For ten thousand years the island was a hidden refuge. Now it is falling apart, and its people have begun to look downward, toward a world their ancestors fled.]=],
		},
		{
			title = "Origins",
			text = [=[The {link:skyborne}shen'dorei{/link} descend from rebels of Eldre'Thalas, the Highborne city in {link:feralas}Feralas{/link} now called {red:dire-maul}Dire Maul{/red}. They rose against Prince {red:tortheldrin}Tortheldrin{/red}, lost their war, and fled west across the sea. When the prince's ships closed in, spirits of the wind lifted a great piece of land into the sky and carried it out of the world. They anchored it in {link:skywall}Skywall{/link} with ancient pylons, and there the exiles built a small, bright civilization among the clouds. Its founder, the masked rebel called the {link:flight-from-eldre-thalas}Shal'nan{/link}, later gave his power to a council chosen by the people.]=],
		},
		{
			title = "The Present Day",
			text = [=[Several centuries ago the {link:vanishing-of-the-wind-spirits}wind spirits{/link} vanished without a word. The pylons have weakened ever since, and whole districts have crumbled into the sky. {link:ruins-of-ban-aethal}Ban'aethal{/link} fell in a single night. Contact with the other isles of the {link:skyborne}shen'dorei{/link} is lost, and refugees who reached Zephras now crowd {link:valanaar}Valanaar{/link} or turn to banditry. Into that fear came the {link:al-aketh}Al'Aketh{/link}, a cult of {link:al-akir}Al'Akir{/link} led by {link:high-priestess-lorthuna}High Priestess Lorthuna{/link}. They seized {link:falaath-village}Falaath Village{/link} and the {link:shrine-of-akir}Shrine of Akir{/link}, and they struck at the pylon watchtowers. Their purpose was to break the wards that hid the island. The {link:windshapers}Windshapers{/link} and the {link:high-order}High Order{/link} despise one another, but they stood with {link:valennia-stormfist}Valennia Stormfist{/link}'s {link:peacekeepers}Peacekeepers{/link} against the cult, and the cult was broken. Its work was not. The wards are gone, and a lord of the Windlord's host has seen Zephras. Now each order sends its young to {link:azeroth}Azeroth{/link}: the Windshapers to the {link:earthen-ring}Earthen Ring{/link} in {link:mulgore}Mulgore{/link}, the High Order to the {link:kirin-tor}Kirin Tor{/link} of {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Inhabitants",
			text = [=[• {b}The Council of Elders.{/b} High Elder {link:talaanis-shadowsong}Talaanis Shadowsong{/link} leads the island's council from {link:valanaar}Valanaar{/link}.
• {b}The {link:windshapers}Windshapers{/link}.{/b} Shamans and seers who guard the sacred stones and seek the lost spirits.
• {b}The {link:high-order}High Order{/link}.{/b} Magisters of Highborne blood who would master the island's magic themselves.
• {b}The {link:peacekeepers}Peacekeepers{/link}.{/b} The island's militia, the nearest thing the {link:skyborne}shen'dorei{/link} have to an army.
• {b}The {link:al-aketh}Al'Aketh{/link}.{/b} Zealots of the {link:al-akir}Windlord{/link}, scattered but not destroyed.
• {b}The Nightclaw.{/b} A secretive circle of druids in the {link:shadowgale-forest}Shadowgale Forest{/link}.
• {b}Beasts.{/b} Vuldren, ursera, prideclaws, hippogryphs and shrieklings, many grown wild since the winds fell silent.]=],
		},
		{
			title = "Lore of the Isle",
			text = [=[• A {link:skyborne}shen'dorei{/link} who comes of age receives an heirloom once carried by one who came before. When its bearer dies, the heirloom is recovered for the next youth.
• The dead are burned, and their ashes are given to the winds.
• Windstones, blue gems full of the raw wind, now light and warm most homes of the island.
• Small recall crystals hold voices. Touched, they let a recording drift out faintly on the air.]=],
		},
	},
})

