			unlock = {
				{ type = "quest", id = 93948 },
			},
			text = [=[The defenders of the {link:west-pylon-watchtower}western watchtower{/link} died at their post. Among the dead was the High Elder's nephew, and his family signet came back to {link:valanaar}Valanaar{/link} in a stranger's hand. Talaanis took the ring and the news with grace. Then he did what an elder must do in such days. He sent the one who brought it to the {link:peacekeepers}Peacekeepers{/link}, for the island needed every willing sword.]=],
		},
