			hint = "Tell the High Elder what was learned on the spires.",
			unlock = {
				{ type = "quest", id = 93836 },
				{ type = "quest", id = 94369 },
			},
			text = [=[After the spires, the leaders of both orders came to Talaanis with the same grim news. The wards were gone, and the island lay open to {link:al-akir}Al'Akir{/link} in his own realm. Each order meant to seek its answer in {link:azeroth}Azeroth{/link}, and Talaanis gave both his blessing. He hoped that whatever they found would bring {link:zephras-isle}Zephras{/link} the stability it had lacked for years.]=],
