	sections = {
		{
			title = "Summary",
			text = [=[Elaadrin Evengale is the Supreme Magister of the {link:high-order}High Order{/link}, the magisters of Highborne blood on {link:zephras-isle}Zephras Isle{/link}. From his lodge in {link:valanaar}Valanaar{/link} he leads those who believe the {link:skyborne}shen'dorei{/link} trusted their elemental patrons too much. He is proud, sharp of tongue and certain of his course. Under his leadership the High Order has found a way through the planes to {link:azeroth}Azeroth{/link}, and a new ally there.]=],
		},
		{
			title = "Significance",
			text = [=[Elaadrin believes that the gifts of the vanished spirits can be matched by the old magic of the {red:highborne}Highborne{/red}, if only his people can relearn it. That magic has grown weak in {link:skywall}Skywall{/link}. So he looked outward. His magisters carved a kind of keyhole through the planes and peered at the world their ancestors had left, and someone on the other side looked back: the {link:kirin-tor}Kirin Tor{/link} of {link:dalaran}Dalaran{/link}. Through him the {link:high-order}High Order{/link} has joined the {link:alliance}Alliance{/link}.]=],
