			hint = "Answer the Supreme Magister after his envoy's fate is known.",
			unlock = {
				{ type = "quest", id = 92834 },
			},
			text = [=[When the cult first turned to violence, Elaadrin had counseled talks. He sent his friend {link:belathaan-brightwish}Belathaan{/link} to the shrine. A box came back to {link:valanaar}Valanaar{/link} holding Belathaan's tongue, painted with silver. Elaadrin wanted no more dialogue. He offered the {link:high-order}High Order{/link}'s full support to the {link:peacekeepers}Peacekeepers{/link}.]=],
