			unlock = {
				{ type = "quest", id = 93835 },
			},
			text = [=[On the spires Elaadrin offered {link:high-priestess-lorthuna}Lorthuna{/link} a swift death if she would yield. She laughed at him. When the {link:al-akir}Windlord{/link}'s servant came, Elaadrin had little to answer with but his courage, until the mages of the {link:kirin-tor}Kirin Tor{/link} arrived and he greeted Archmage {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} for the first time.]=],
