Add({
	kind = "figure",
	id = "al-akir",
	title = "Al'Akir",
	aliases = { "Al'Akir the Windlord", "Windlord" },
	subtitle = "The Windlord, Lord of Skywall",
	tier = "A",
	region = "skywall",
	allegiance = "The Elemental Plane",
	found = "Somewhere in the endless storms of Skywall",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Al'Akir the Windlord is the lord of the air and the master of {link:skywall}Skywall{/link}. He is one of the four great elemental lords, a peer of Ragnaros of the fire, Neptulon of the tides and Therazane of the stone. Wind and storm are his servants, and the elementals of the air are his host. No mortal chronicle tells of anyone who has stood before him and returned.]=],
		},
		{
			title = "Significance",
			text = [=[For the {link:elements}elemental lords{/link}, mortal peoples matter little. The Windlord did not know that the {link:skyborne}shen'dorei{/link} existed. For ten thousand years, spirits of his own realm hid {link:zephras-isle}Zephras Isle{/link} from his sight behind the wards of its pylons, and the elves grew up in his domain without knowing him. The spirits who raised them would not speak his name. When the elves asked, the spirits grew uneasy, turned the question aside, and told them they had nothing to fear on their isles. Some shen'dorei came to doubt that he was real. Others, seeing across the plane with their skysight, glimpsed his power and began to worship it.]=],
		},
		{
			title = "Deeds",
			text = [=[• In the first age of the world, he and the other elemental lords served the Old Gods, until the servants of the titans bound the elementals in a realm apart.
• He rules {link:skywall}Skywall{/link} with a host of air elementals and lords of the winds.
• His name is worshipped by the {link:al-aketh}Al'Aketh{/link}, who call themselves his faithful.
• His missionaries warn that any who come to his faithful under false pretenses will feel his wrath.
• His servant {link:rohash}Rohash{/link} boasts that the armies of the Windlord are without end in Skywall.
• Fear of his coming now drives both orders of the {link:skyborne}shen'dorei{/link} to seek help in {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of this age describes the Windlord's face, his seat in {link:skywall}Skywall{/link}, or his will. The {link:skyborne}shen'dorei{/link} know him only by the silence of their spirits and the boasts of his servants.]=],
		},
	},
	chapters = {
		{
			key = "the-windlord-s-gaze",
			title = "The Windlord's Gaze",
			hint = [=[Learn what the Earthen Ring and the Kirin Tor told the orders of the Windlord.]=],
			unlock = {
				{ type = "quest", id = 93836 },
				{ type = "quest", id = 94369 },
			},
			text = [=[When {link:high-priestess-lorthuna}Lorthuna{/link} lit her beacon on the {link:rohashi-spires}Rohashi Spires{/link}, {link:rohash}Rohash{/link}, the Lord of the East Wind, answered it. He was astonished that such a place could exist in the Windlord's realm, and he praised his "wayward brothers" for hiding it so well. He promised that his lord would hear of it. The shamans of the {link:earthen-ring}Earthen Ring{/link} and the mages of the {link:kirin-tor}Kirin Tor{/link} told the elves what they knew of the elemental lords. What they heard gave the leaders of both orders good reason to be afraid. In his own domain, Al'Akir could destroy them whenever he chose.]=],
		},
	},
	mentions = {
		{
			text = [=[The Next Step, where an elder names him the supposed ruler of {link:skywall}Skywall{/link}]=],
			unlock = {
				{ type = "quest", id = 92472 },
			},
		},
		{
			text = [=[{link:falaath-village}Falaath Village{/link}, the cult's call to serve him]=],
			unlock = {
				{ type = "quest", id = 92529 },
			},
		},
	},
	bonds = {
