			text = [=[Aetheen of the Gales is a member of {link:shadow-council}the Council{/link} of Elders of {link:zephras-isle}Zephras Isle{/link}. She has come to {link:thendal-village}Thendal Village{/link} to read the flow of the winds in the grove, and to judge the young {link:skyborne}shen'dorei{/link} who come of age there. She watches before she speaks. By the time a youth meets her, she already knows a great deal about them.]=],
		},
		{
			title = "Significance",
			text = [=[Aetheen is the council's eye upon the next generation. In a time when the island needs every able hand, she decides which of the young are ready to leave the shelter of the grove. She is also among the first to name the danger plainly to them: the {link:al-aketh}Al'Aketh{/link}, zealots of a "supposed" ruler of {link:skywall}Skywall{/link}, whose power and ambitions grow each day.]=],
		},
		{
			title = "Deeds",
			text = [=[• She reads the winds of {link:thendal-village}Thendal Grove{/link} for the council.
