Add({
	kind = "figure",
	id = "high-priestess-lorthuna",
	title = "High Priestess Lorthuna",
	aliases = { "Lorthuna" },
	subtitle = "High Priestess of the Al'Aketh",
	tier = "B",
	region = "zephras-isle",
	npc = { 252076, 252957, 256249 },
	allegiance = "Al'Aketh",
	found = "The Shrine of Akir and the spires above it",
	unlock = {
		{ type = "target" },
