	hint = "Face the high priestess of the cult of the Windlord.",
	sections = {
		{
			title = "Summary",
			text = [=[High Priestess Lorthuna leads the {link:al-aketh}Al'Aketh{/link}, the cult of {link:al-akir}Al'Akir{/link} on {link:zephras-isle}Zephras Isle{/link}. She was once a {link:windshapers}Windshaper{/link} and a sister of {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}'s order. Now she rules the {link:shrine-of-akir}Shrine of Akir{/link} and speaks of a great work that will bring the Windlord to her people. She is cold, clever and cruel, and her followers call themselves the instruments of her will.]=],
		},
		{
			title = "Significance",
			text = [=[Lorthuna saw what the rest of her people did not: that the pylons of {link:zephras-isle}Zephras{/link} were wards as well as anchors. She turned that secret into a weapon. Her cult seized {link:falaath-village}Falaath Village{/link}, struck at the pylon watchtowers and brought the wards down. Whatever became of her, her work cannot be undone. Zephras now lies open before its {link:al-akir}Windlord{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• She sent raiders and preachers across the island from the {link:shrine-of-akir}Shrine of Akir{/link}.
• She met {link:skypriest-aanders}Skypriest Aanders{/link} at Falaath and set her attacks on Shen'dar and the {link:west-pylon-watchtower}western watchtower{/link} in motion.
• She had the {link:high-order}High Order{/link} envoy {link:belathaan-brightwish}Belathaan Brightwish{/link} killed and sent his tongue back to {link:valanaar}Valanaar{/link}.
• She lit a beacon on the {link:rohashi-spires}Rohashi Spires{/link} for the servants of the {link:al-akir}Windlord{/link}.]=],
		},
	},
	chapters = {
		{
			key = "the-guest-at-falaath",
			title = "The Guest at Falaath",
			hint = "Learn what the cult plans for the Shen'dar Highlands.",
			unlock = {
				{ type = "quest", id = 92528 },
			},
			text = [=[A recruit who went among the faithful of Falaath was told to keep away from the inn, where the skypriest was receiving a guest. The guest was Lorthuna. Her orders were brief. She had other business, and this was only one piece of her game. {link:skypriest-aanders}Aanders{/link} would take the {link:west-pylon-watchtower}western watchtower{/link}, and Cyclas would take {link:shen-dar-village}Shen'dar Village{/link}.]=],
		},
		{
			key = "the-beacon",
			title = "The Beacon",
			hint = "Follow the high priestess to the spires above her shrine.",
			unlock = {
				{ type = "quest", id = 92646 },
				{ type = "quest", id = 93835 },
			},
			text = [=[On the spires, Lorthuna told her enemies they were too late. The wards had been down for days. She was lighting a beacon. When the Lord of the East Wind came, she hailed him and asked to be brought before the {link:al-akir}Windlord{/link} as the herald of his glory. {link:rohash}Rohash{/link} struck her aside and sent her flying into the endless sky.]=],
		},
