			text = [=[Rohash is the Lord of the East Wind, one of the great lords of the air who serve {link:al-akir}Al'Akir{/link} in {link:skywall}Skywall{/link}. He is mighty, mocking and delighted by the suffering of lesser beings. He came to {link:zephras-isle}Zephras Isle{/link} when {link:high-priestess-lorthuna}Lorthuna{/link}'s beacon called him.]=],
		},
		{
			title = "Significance",
			text = [=[Rohash is the first servant of the {link:al-akir}Windlord{/link} known to have seen {link:zephras-isle}Zephras Isle{/link}. He had never heard of the island or its people. Its discovery amazed him, and he understood at once what it meant. The spirits who had sheltered the elves were his own "wayward brothers", and they had hidden the island well. With the wards gone, he could carry the secret to his lord.]=],
		},
		{
			title = "Deeds",
			text = [=[• He answered {link:high-priestess-lorthuna}Lorthuna{/link}'s beacon on the {link:rohashi-spires}Rohashi Spires{/link}.
• He cast the high priestess aside when she presumed to command him.
• He called up the armies of the {link:al-akir}Windlord{/link} against the elves.
• He withdrew when the {link:earthen-ring}Earthen Ring{/link} and the {link:kirin-tor}Kirin Tor{/link} stood with the {link:skyborne}shen'dorei{/link}.
• He mocked the elves' hope to hold out, saying his lord's armies were endless in that realm.]=],
		},
	},
	chapters = {
