			unlock = {
				{ type = "quest", id = 92646 },
				{ type = "quest", id = 93835 },
			},
			text = [=[Rohash laughed at the elves and at the friends they had found in low places. He wondered aloud whether his lord would enslave them or merely devour them. When {link:muln-earthfury}Muln Earthfury{/link} told him the Ring had no quarrel with him, Rohash chose to depart. Before he went, he gave the elves his promise. They were guests in his lord's realm only until the {link:al-akir}Windlord{/link}'s judgement came. They would not know when it would come, but it would come.]=],
		},
