Add({
	kind = "topic",
	id = "windshapers",
	title = "Windshapers",
	aliases = { "Windshaper" },
	category = "group",
	region = "zephras-isle",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 92595 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Windshapers are the shamans and seers of the {link:skyborne}Skyborne{/link}. They descend from the first shen'dorei who received the {link:vanishing-of-the-wind-spirits}wind spirits{/link}' gift of skysight, the power to see across the elemental plane. For ages they were the spiritual guides of {link:zephras-isle}Zephras Isle{/link}. They guard its sacred standing stones, and they tend the constructs and instruments the spirits left behind.]=],
		},
		{
			title = "Their Creed",
			text = [=[The Windshapers hold that their people owe the {link:vanishing-of-the-wind-spirits}wind spirits{/link} a debt that can never be fully repaid. They have sworn to find the spirits and restore the old ways. Without the spirits, they say, they are nearly blind to what happens in {link:skywall}Skywall{/link}. Some of them fear that the fault for the spirits' departure is their own. They distrust the {link:high-order}High Order{/link}, whom they call arrogant heirs of the Highborne who seek to master what they should honor. Where the High Order sees risen ley lines as a gift, the Windshapers see wounds in the land.]=],
		},
		{
			title = "In the Present Day",
			text = [=[Their magic has faded since the spirits left, and blood lies between them and the {link:high-order}High Order{/link}. Their leader, the {link:ayessa-dawnsinger}Grand Skyseer{/link} Ayessa Dawnsinger, searched the planes with her skysight and found the {link:earthen-ring}Earthen Ring{/link} of {link:azeroth}Azeroth{/link}. Through the Ring the Windshapers have joined the {link:horde}Horde{/link}. Their vanguard now sails from {link:valanaar}Valanaar{/link} to {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Add({
	kind = "topic",
